def rank_categories_by_text(text: str, *, max_categories: int = 4) -> list[int]:
    """根据应用名/源码关键词为 LLM 预筛二级分类（默认工具类兜底）。"""
    blob = (text or "").lower()
    scores: dict[int, int] = {}
    for category_id, keywords in _CATEGORY_KEYWORDS.items():
        score = sum(1 for kw in keywords if kw.lower() in blob)
        if score:
            scores[category_id] = score

    if not scores:
        return [10000000]

    ranked = sorted(scores.items(), key=lambda item: (-item[1], item[0]))
    picked = [cid for cid, _ in ranked[:max_categories]]
    if 10000000 not in picked:
        picked.append(10000000)
    return picked[: max_categories + 1]


def find_entry_by_tag_id(tag_id: int) -> dict | None:
    for item in CATEGORY_TAG_ENTRIES:
        if item["tagId"] == tag_id:
            return item
    return None


def validate_category_tag(second_category_id: int, tag_id: int) -> dict:
    entry = find_entry_by_tag_id(tag_id)
    if not entry:
        raise ValueError(f"无效 tagId: {tag_id}")
    if entry["secondCategoryId"] != second_category_id:
        raise ValueError(
            f"tagId {tag_id} 与 secondCategoryId {second_category_id} 不匹配，"
            f"应为 {entry['secondCategoryId']}（{entry['category']} / {entry['tag']}）"
        )
    return entry
